'use strict';
const $=id=>document.getElementById(id),R=ExtendedRecord,gate=new R.RunGate();let worker=null,sequence=0,snapshot=null,runInput=null,start=0,operationEpoch=0;
const f=x=>Number.isFinite(x)?x.toPrecision(6):'不可用';
function generate(){invalidate('信道已改变，请重新运行。');$('channel').value=JSON.stringify(R.seeded(Number($('nt').value),Number($('seed').value)),null,2);}
function invalidate(message){operationEpoch++;if(gate.current&&worker)worker.postMessage({type:'cancel',runId:gate.current});gate.clear();clearResult();$('cancel').disabled=true;if(message)$('status').textContent=message;}
function clearResult() {snapshot=null;$('export').disabled=true;$('output').replaceChildren();$('origin').textContent='当前没有已完成结果';}
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function card(title,m,feasible,imported){const el=node('article',undefined,'card');el.append(node('h3',title),node('p',feasible?(imported?'记录中的可行性检查通过':'可行性检查通过'):(imported?'记录：未接受为可行方案':'未接受为可行方案'),'badge'+(feasible?'':' warn')),node('p','完整响应复MSE下界（不是角度CRB）'),node('div',f(m.radar.fullResponseMseBound),'number'));const dl=node('dl');for(const [k,v] of [['最低SINR（线性）',f(Math.min(...m.users.map(u=>u.sinr)))],['最低SINR / 门槛',f(Math.min(...m.users.map(u=>u.ratioToThreshold)))],['实际功率 / mW',f(m.powerMw)],['逆迹 / (1/mW)',f(m.radar.traceInversePerMw)],['协方差状态',m.radar.status]])dl.append(node('dt',k),node('dd',v));el.append(dl,node('h4','R特征值 / mW'));const bars=node('div',undefined,'spectrum'),ev=m.radar.eigenvaluesMw,max=Math.max(...ev,1);bars.setAttribute('aria-hidden','true');ev.forEach(v=>{const bar=node('div',undefined,'bar');bar.style.height=Math.max(0,v)/max*100+'%';bars.append(bar);});el.append(bars,node('p',ev.map(f).join(' · '),'values'),node('h4','接收功率分解 / mW'));const sc=node('div',undefined,'scroll'),table=node('table'),tr=node('tr');['用户','有用数据','其他用户数据','探测流','噪声'].forEach(v=>tr.append(node('th',v)));const head=node('thead');head.append(tr);table.append(head);const body=node('tbody');m.users.forEach((u,i)=>{const row=node('tr');[i+1,f(u.desiredMw),f(u.dataInterferenceMw),f(u.probingInterferenceMw),'1'].forEach(v=>row.append(node('td',v)));body.append(row);});table.append(body);sc.append(table);el.append(sc);return el;}
function render(env,imported){snapshot=env;$('export').disabled=false;const r=env.record;$('origin').textContent=(imported?'导入历史记录 · 未重算；仅结构检查，未独立重新认证':'当前Worker实时结果')+' · '+env.runId+' · Nt '+env.input.Nt+' · Γ '+env.input.gammaDb+' dB';$('output').replaceChildren();const out=$('output');out.append(node('p',(imported?'记录状态：':'状态：')+r.status+' · '+(imported?'记录物理验收：':'物理验收：')+(r.physicalGate.passed?'passed':'not passed'),'badge'+(r.physicalGate.passed?'':' warn')));if(r.failureReason)out.append(node('p',typeof r.failureReason==='string'?r.failureReason:JSON.stringify(r.failureReason)));if(r.diagnosticsFailureReason)out.append(node('p','Optional diagnostics 不可用: '+r.diagnosticsFailureReason));if(r.physicalGate.failures?.length)out.append(node('p','验收问题：'+r.physicalGate.failures.join(', ')));if(r.certificate)out.append(node('p',(imported?'记录浮点证书':'浮点证书')+' · 相对gap '+f(r.certificate.relativeGap)+' · 系数残差 '+f(r.certificate.epigraphCoefficientResidual)));if(r.recovery)out.append(node('p','恢复协方差相对缺陷：'+f(r.recovery.covarianceRelativeDefect)));if(r.metrics&&r.baseline){const box=node('div',undefined,'comparison');box.append(card('构造恢复',r.metrics,r.status==='converged'&&r.physicalGate.passed,imported),card('主特征对基线',r.baseline.metrics,r.baseline.feasible,imported));out.append(box,node('p','基线共用同一松弛数据块，只保留原探测协方差；不重新缩放功率。必须同时比较实际用能与可行性。','small'));}else out.append(node('p','当前终态没有可接受的波束比较。预算耗尽或取消不证明不可行。'));}
function ensureWorker(){if(worker)return worker;worker=new Worker('worker.js');worker.onmessage=({data:m})=>{if(!gate.accept(m))return;if(m.type==='progress'){$('status').textContent='正在计算 '+m.runId+' · 迭代 '+m.progress.iterations;return;}if(m.type==='started')return;$('cancel').disabled=true;gate.clear();if(m.type==='error'){$('status').textContent='Worker错误：'+m.message;return;}try{render(R.create(m.runId,runInput,m.record),false);$('status').textContent='已完成：'+m.record.status+' · Worker耗时 '+(m.workerWallMs/1000).toFixed(2)+' s · 浏览器观测耗时 '+((performance.now()-start)/1000).toFixed(2)+' s （含调度和传输，不是性能基准）';}catch(e){clearResult();$('status').textContent='结果校验失败：'+e.message;}};worker.onerror=e=>{gate.clear();clearResult();$('cancel').disabled=true;$('status').textContent='Worker无法运行：'+e.message+'。请通过HTTP(S)访问，不要使用file://。';worker.terminate();worker=null;};return worker;}
$('form').onsubmit=e=>{e.preventDefault();try{const nt=Number($('nt').value),input=R.input({Nt:nt,Nr:nt+4,K:2,L:30,powerMw:1000,communicationNoiseMw:1,radarNoiseMw:1,gammaDb:Number($('gamma').value),H:JSON.parse($('channel').value)});const w=ensureWorker();operationEpoch++;runInput=R.freeze(JSON.parse(JSON.stringify(input)));const id='run-'+Date.now()+'-'+(++sequence);gate.begin(id);clearResult();start=performance.now();$('cancel').disabled=false;$('status').textContent='正在启动 '+id;w.postMessage({type:'run',runId:id,input:runInput});}catch(e){invalidate('输入错误：'+e.message);}};
$('cancel').onclick=()=>{if(gate.current){worker.postMessage({type:'cancel',runId:gate.current});$('status').textContent='已请求取消，等待Worker确认';$('cancel').disabled=true;}};
$('generate').onclick=generate;$('nt').onchange=generate;for(const id of ['gamma','channel','seed'])$(id).oninput=()=>invalidate('输入已改变，请重新运行。');window.addEventListener('pagehide',()=>{invalidate('页面已离开，旧计算已清空；返回后请重算。');if(worker){worker.terminate();worker=null;}});
$('export').onclick=()=>{if(!snapshot)return;const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='extended-crb-'+snapshot.runId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;const epoch=++operationEpoch;try{if(file.size>5000000)throw Error('文件超过5 MB');const text=await file.text();if(epoch!==operationEpoch)return;const env=R.parse(text);if(gate.current)worker.postMessage({type:'cancel',runId:gate.current});gate.clear();$('cancel').disabled=true;render(env,true);$('status').textContent='已导入不可变历史记录；导入不执行或独立验证求解器。';}catch(err){if(epoch===operationEpoch)$('status').textContent='导入被拒绝：'+err.message;}finally{if(epoch===operationEpoch)e.target.value='';}};
generate();
